type Visitor interface{}                                  // degenerate base
type CircleVisitor interface{ VisitCircle(*Circle) }

func (c *Circle) Accept(v Visitor) {
    if cv, ok := v.(CircleVisitor); ok {                  // !ok == visitor cannot visit Circle
        cv.VisitCircle(c)
        return
    }
    log.Printf("visitor %T cannot visit Circle", v)
}
